self._adv_title.setStyleSheet(
            f"color: {themes.color('heading')}; background: transparent; {label_font} font-weight: bold;"
        )

self._toggle.setAccessibleName(
            f"{self._name} — {tr('plugins.disable' if self._toggle.isChecked() else 'plugins.enable', default='Toggle Enabled')}"
        )

val.setStyleSheet(
            f"font-size: {fs_sm}px; color: {themes.color('heading')}; background: transparent; border: none;"
        )

self.setStyleSheet(
            f"""
            #quickLookCard {{
                background: {card_bg};
                border: {border_width}px solid {card_border};
                border-radius: {radius_lg}px;
            }}
            #quickLookHeader {{
                background: {header_bg};
                border-bottom: {border_width}px solid {card_border};
                border-top-left-radius: {radius_lg}px;
                border-top-right-radius: {radius_lg}px;
            }}
            #quickLookFooter {{
                background: {footer_bg};
                border-top: {border_width}px solid {card_border};
                border-bottom-left-radius: {radius_lg}px;
                border-bottom-right-radius: {radius_lg}px;
            }}
            #quickLookCanvasArea {{
                background: {canvas_bg};
            }}
            #quickLookTitle {{
                color: {color_heading};
                font-size: {fs_md}px;
                font-weight: bold;
            }}
            #quickLookSpecPill {{
                background: {pill_bg};
                color: {color_accent};
                border: {border_width}px solid {pill_border};
                border-radius: {radius_xs}px;
                padding: {pad_y_xs}px {pad_x_xs}px;
                font-size: {fs_xs}px;
                font-family: monospace;
                font-weight: bold;
            }}
            #quickLookIndex {{
                color: {color_muted};
                font-size: {fs_sm}px;
                font-family: monospace;
            }}
            #quickLookNavBtn {{
                background: {nav_btn_bg};
                border: {border_width}px solid {card_border};
                border-radius: {nav_btn_radius}px;
            }}
            #quickLookNavBtn:hover {{
                background: {nav_btn_hover_bg};
                border-color: {card_border_hover};
            }}
            #quickLookKbd {{
                background: {kbd_bg};
                color: {color_heading};
                border-radius: {radius_xs}px;
                padding: {pad_y_xxs}px {pad_x_xs}px;
                font-size: {fs_xs}px;
                font-family: monospace;
            }}
            #quickLookFooterText {{
                color: {color_muted};
                font-size: {fs_sm}px;
            }}
            """
        )
